class Solution:
    def countIslands(self, grid: List[List[int]], k: int) -> int:
        def flood(i: int, j: int) -> int:
            s = grid[i][j]
            grid[i][j] = 0
            stk = [(i, j)]
            while stk:
                i, j = stk.pop()
                for a, b in pairwise(dirs):
                    x, y = i + a, j + b
                    if 0 <= x < m and 0 <= y < n and grid[x][y]:
                        s += grid[x][y]
                        grid[x][y] = 0
                        stk.append((x, y))
            return s

        m, n = len(grid), len(grid[0])
        dirs = (-1, 0, 1, 0, -1)
        ans = 0
        for i in range(m):
            for j in range(n):
                if grid[i][j] and flood(i, j) % k == 0:
                    ans += 1
        return ans

class Solution {
    public int countIslands(int[][] grid, int k) {
        int m = grid.length, n = grid[0].length;
        int[] dirs = {-1, 0, 1, 0, -1};
        Deque<int[]> stk = new ArrayDeque<>();
        int ans = 0;
        for (int i = 0; i < m; ++i) {
            for (int j = 0; j < n; ++j) {
                if (grid[i][j] == 0) {
                    continue;
                }
                long s = grid[i][j];
                grid[i][j] = 0;
                stk.push(new int[] {i, j});
                while (!stk.isEmpty()) {
                    int[] p = stk.pop();
                    int x0 = p[0], y0 = p[1];
                    for (int d = 0; d < 4; ++d) {
                        int x = x0 + dirs[d], y = y0 + dirs[d + 1];
                        if (x >= 0 && x < m && y >= 0 && y < n && grid[x][y] > 0) {
                            s += grid[x][y];
                            grid[x][y] = 0;
                            stk.push(new int[] {x, y});
                        }
                    }
                }
                if (s % k == 0) {
                    ++ans;
                }
            }
        }
        return ans;
    }
}

